import json,hashlib,sys,datetime
from pathlib import Path
ROOT=Path.cwd();sys.path.insert(0,'reader');from bilingual import validate_translations,merge_overlay

def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
for paper in ['icml2025-coalition','icml2024-layerwise']:
 P=Path('corpus/public/reader')/paper;d=json.loads((P/'content.json').read_text());validation=validate_translations(d,strict=True)
 def controls(x):
  if isinstance(x,str):assert not any(ord(c)<32 and c not in '\n\r\t' for c in x),repr(x)
  elif isinstance(x,list):
   for y in x:controls(y)
  elif isinstance(x,dict):
   for y in x.values():controls(y)
 controls(d)
 report=json.loads((P/'verification/report.json').read_text());assert report['status']=='passed';assert all(r['status']=='passed' for r in report['declarations']);assert all(c['exit_code']==0 for c in report['commands'])
 for f in report['source_files']:assert sha(Path(f['path']))==f['sha256'],f['path']
 for r in d['results']:
  for key in ['report_path','source_path']:
   value=r.get('lean',{}).get(key)
   if value:assert not Path(value).is_absolute(),(r['id'],key,value)
 (P/'verification/translation-validation.json').write_text(json.dumps(validation,ensure_ascii=False,indent=2)+'\n')
 specific=(['The source coalition quotient remains undefined for the empty coalition; nonempty proofs do not redefine it.','Symmetry alpha/beta and additivity are refuted with globally L1-optimal decompositions. The Dummy witness only refutes the displayed arbitrary-split definition, not an optimizer-selected version.','R, R-prime, and Q finite-sum comparisons are proved, with zero denominators separately retained.','The Shapley coefficient kernel is compiled, while cardinality grouping is a human adaptation. The Banzhaf signed coefficient is fully compiled. Toy finite pure-AND sums are compiled; the actual binary-mask bridge remains a human adaptation.'] if paper=='icml2025-coalition' else ['Original Eq.(15) keeps its missing binomial coefficient and is repaired by full finite-subset cancellation. Eq.(16) sign omission is separate from the valid grouped zero sums.','Fixed and remasked games are distinct, especially OR dividends. The remasked adapter restricts a fixed split; an independently relearned split is separately instantiated with its original empty convention.','The nonempty OR transform and the special empty baseline are distinct. The printed coordinate equality in Eq.(13) has a source-definition counterexample.','Eq.(8) is refuted for the original strict 5-percent threshold, one-sample normalization, and globally L1-optimal pure-AND games. Formal support/metrics are compiled; optimizer optimality remains a human proof. The witness refutes only the first clause.','Lemma 3.4 and OR-sparsity inheritance retain the unresolved external component conditions and unquantified error, rather than using newly added assumptions.'])
 review={'schema_version':1,'paper_id':paper,'generated_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'review_status':'agent_semantic_reviewed_not_user_approved','english_results':len(d['results']),'proof_step_identity_and_formula_fields':'exactly protected by bilingual merge; passed','inline_tex_comparison':'Differences are reported for human review, not automatically declared equivalent. TeX rewrites and the critical scope-sensitive mathematics listed below were manually checked.','source_propositions_and_assumptions':'preserved; proof-only repairs are separated from source errors/counterexamples','critical_semantic_checks':specific,'original_author_proof_classification':'Full transcriptions, parent components, and no-local-proof entries are distinct; project explanations are not called author proofs.','content_inputs':[{'path':str(P/n),'sha256':sha(P/n)} for n in ['content.json','symbols.json','issues.json','shared-dependencies.json']],'verification_report_sha256':sha(P/'verification/report.json'),'source_semantics_automatically_verified':False,'user_review_status':'pending'}
 (P/'verification/bilingual-semantic-review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n');print(paper,'frozen',report['checked_declarations'],'rows passed; current hashes; English strict passed')
P=Path('corpus/public/translations');overlay=json.loads((P/'iclr2024-sparse.en.json').read_text());raw=json.loads(Path('research/full-proof-integration-20260930/iclr2024-sparse/content.json').read_text())
for r in raw['results']:r.setdefault('translations',{})['en']=overlay['results'][r['id']]
validate_translations({'results':raw['results'],'shared_proofs':[]},strict=True)
review={'schema_version':1,'paper_id':'iclr2024-sparse','review_status':'agent_semantic_reviewed_not_user_approved','translated_results':42,'translated_steps':sum(len(r.get('proof_steps',[])) for r in overlay['results'].values()),'issue_explanations':len(overlay.get('issues',{})),'critical_semantic_checks':['Derivative cutoff retains the original global classical mixed-derivative quantifiers and actual prefix existence; no analytic or polynomial premise is added.','The Case 2 counterfamily refutes only the extra same-order inference, not the parent T2/T3 or total polynomial sparsity relative to 2^n.','T2 includes the zero-mean branch and M=n; the M=0/undefined-parameter reading is separately recorded.','T3 is applied within the original noncanceling Case 1 and does not assign values to 0/0.','Transfer counterexample uses one model and same-class samples with disjoint singleton supports.','T2/T3 and transfer-inference formulas were manually rewritten as whole TeX expressions; protected formula fields, step IDs, and Lean machine mappings are inherited.'],'sidecars':[{'path':str(P/n),'sha256':sha(P/n)} for n in ['iclr2024-sparse.en.json','shared-sparse.en.json']],'source_semantics_automatically_verified':False,'user_review_status':'pending'}
(P/'iclr2024-sparse.semantic-review.json').write_text(json.dumps(review,ensure_ascii=False,indent=2)+'\n');print('Sparse sidecars frozen',len(overlay['results']),'English results')
